const AchievementBar: React.FC<{ value: number; target: number; unit: string }> = ({
  value,
  target,
  unit,
}) => {
  const rate = target > 0 ? Math.min(100, (value / target) * 100) : 0;
  const color = rate >= 95 ? 'success.main' : rate >= 80 ? 'warning.main' : 'error.main';
  return (
    <Box sx={{ minWidth: 120 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
        <Typography
          variant='caption'
          color='text.secondary'
        >
          {rate.toFixed(1)}%
        </Typography>
        <Typography
          variant='caption'
          color='text.secondary'
        >
          目标 {target.toLocaleString()}
          {unit}
        </Typography>
      </Box>
      <LinearProgress
        variant='determinate'
        value={rate}
        sx={{
          height: 6,
          borderRadius: 3,
          bgcolor: 'grey.200',
          '& .MuiLinearProgress-bar': { bgcolor: color },
        }}
      />
    </Box>
  );
};

