          {tab === 'budget' && renderBudgetTable()}
          {tab === 'violations' && renderViolationsTable()}
        </Paper>
      </DashboardTemplate>

      <ConfirmDialog
        isOpen={confirmDialog.open}
        onClose={closeResolve}
        onConfirm={() => {
          if (confirmDialog.violation) {
            resolveMutation.mutate(confirmDialog.violation.id);
          }
          closeResolve();
        }}
        title='处理违规'
        message={

slostatuspage.;\n______\n_____join_'_'_;\n__return__\n:
;
    })
    .join(' ');
  return (
    <Box sx={{ width: '100%', height }}>
      <svg
        width='100%'
        height='100%'
        viewBox='0 0 100 40'
        preserveAspectRatio='none'
      >
        <polyline
          points={points}
          fill='none'
          stroke={color}
          strokeWidth='1.2'
        />
      </svg>
    </Box>
  );
};

